import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import api from '../api/axios';

export default function Home() {
  const [internships, setInternships] = useState([]);

  useEffect(() => {
    api.get('/internships').then(r => setInternships(r.data.slice(0, 6))).catch(() => {});
  }, []);

  return (
    <>
      <div className="home-hero">
        <h1>Find Your Perfect Internship</h1>
        <p>Discover opportunities tailored to your department and batch</p>
        <div className="hero-actions">
          <Link to="/register" className="btn btn-white">Get Started</Link>
          <Link to="/login" className="btn btn-white-outline">Login</Link>
        </div>
      </div>
      <div className="container">
        <div className="section-title">Latest Internships</div>
        {internships.length === 0 ? (
          <div className="empty-state"><p>No internships posted yet.</p></div>
        ) : (
          <div className="grid">
            {internships.map(i => (
              <div key={i.id} className="internship-card">
                <h3>{i.title}</h3>
                <div className="company">{i.company}</div>
                <div className="meta">💰 {i.stipend || 'N/A'} &nbsp;|&nbsp; 📅 {i.deadline}</div>
                <div className="tags">
                  {i.eligibleDepartments?.map(d => <span key={d} className="tag">{d}</span>)}
                  {i.eligibleBatches?.map(b => <span key={b} className="tag tag-batch">{b}</span>)}
                </div>
                <Link to={`/internships/${i.id}`} className="btn btn-outline btn-sm">View Details</Link>
              </div>
            ))}
          </div>
        )}
      </div>
    </>
  );
}
